-- -------------------------------------------------------------------------
-- item_set_names for the 45 Cataclysm sets added in file 01
-- -------------------------------------------------------------------------
-- Silences the 248 "Item set part (Entry: N) does not have entry in
-- `item_set_names`, adding data from `item_template`." lines at every boot.
--
-- Nothing is broken without this -- ObjectMgr::LoadItemSetNames falls back to the
-- item_template name and InventoryType at runtime -- but the fallback is not
-- persisted, so it re-logs on every start. These rows make it quiet.
--
-- Only entries that actually appear in a set ItemID array are inserted: the loader
-- warns "Item set name (Entry: N) not found in ItemSet.dbc, data useless" for any
-- row that does not, and it reads only the FIRST 10 slots (MAX_ITEM_SET_ITEMS).
--
-- Values are taken straight from item_template by SELECT rather than restated, so
-- they cannot drift from the item name and slot, and no name escaping is needed.
--
-- Apply AFTER 01 (which creates the sets) and after 05 (which is where these items
-- get their final data). Idempotent.
-- -------------------------------------------------------------------------

DELETE FROM `item_set_names` WHERE `entry` IN (
  20177, 20181, 20184, 54471, 54472, 54473, 54474, 54475, 54476, 54477, 54478, 54479,
  54480, 54481, 54482, 54483, 54484, 54485, 54486, 56481, 56482, 56483, 56484, 56490,
  56491, 56494, 56495, 56498, 56499, 56504, 56505, 56508, 56509, 56512, 56513, 60243,
  60244, 60245, 60246, 60247, 60276, 60277, 60278, 60279, 60280, 60286, 60287, 60288,
  60289, 60290, 60298, 60299, 60300, 60301, 60302, 60303, 60304, 60305, 60306, 60307,
  60308, 60309, 60310, 60311, 60312, 60313, 60314, 60315, 60316, 60317, 60318, 60319,
  60320, 60321, 60322, 60328, 60329, 60330, 60331, 60332, 60349, 60350, 60351, 60352,
  60353, 63537, 63538, 64928, 64929, 64930, 64931, 64932, 64933, 64934, 64935, 64936,
  64937, 64938, 64939, 64940, 64941, 64942, 64943, 64944, 64945, 64946, 64947, 64948,
